representation.shell_command:
python3 /dev/stdin '$(inputs.pdbfile.path)' > ss_report.txt <<'PYEOF'
import sys, math

path = sys.argv[1]
helix_recs, sheet_recs = [], []
res_list, seen = [], {}
for line in open(path):
    rec = line[:6]
    if rec.startswith('HELIX'):
        helix_recs.append(line.rstrip('\n'))
    elif rec.startswith('SHEET'):
        sheet_recs.append(line.rstrip('\n'))
    elif rec.startswith('ENDMDL'):
        break
    elif rec == 'ATOM  ':
        if line[16] not in (' ', 'A'):
            continue
        name = line[12:16].strip()
        if name not in ('N', 'CA', 'C', 'O'):
            continue
        key = (line[21], line[22:26].strip(), line[26])
        if key not in seen:
            r = {'resname': line[17:20].strip(), 'chain': line[21], 'resseq': line[22:26].strip(), 'icode': line[26], 'atoms': {}}
            seen[key] = r
            res_list.append(r)
        r = seen[key]
        if name not in r['atoms']:
            r['atoms'][name] = (float(line[30:38]), float(line[38:46]), float(line[46:54]))

res = [r for r in res_list if all(a in r['atoms'] for a in ('N','CA','C','O'))]
n = len(res)

def d(a, b):
    return math.sqrt((a[0]-b[0])**2 + (a[1]-b[1])**2 + (a[2]-b[2])**2)

cont = [False]*n
for i in range(1, n):
    if res[i]['chain'] == res[i-1]['chain'] and d(res[i-1]['atoms']['C'], res[i]['atoms']['N']) < 2.5:
        cont[i] = True

for i, r in enumerate(res):
    r['H'] = None
    if i > 0 and cont[i] and r['resname'] != 'PRO':
        C = res[i-1]['atoms']['C']; O = res[i-1]['atoms']['O']; N = r['atoms']['N']
        v = (C[0]-O[0], C[1]-O[1], C[2]-O[2])
        L = math.sqrt(v[0]**2 + v[1]**2 + v[2]**2)
        r['H'] = (N[0]+v[0]/L, N[1]+v[1]/L, N[2]+v[2]/L)

Q = 0.42*0.20*332.0

def energy(ai, aj):
    don = res[aj]; acc = res[ai]
    if don['H'] is None:
        return 0.0
    if d(acc['atoms']['CA'], don['atoms']['CA']) > 9.0:
        return 0.0
    N = don['atoms']['N']; H = don['H']; C = acc['atoms']['C']; O = acc['atoms']['O']
    rON = d(O,N); rCH = d(C,H); rOH = d(O,H); rCN = d(C,N)
    if min(rON, rCH, rOH, rCN) < 0.5:
        return 0.0
    return Q*(1.0/rON + 1.0/rCH - 1.0/rOH - 1.0/rCN)

hbset = set()
for i in range(n):
    for j in range(n):
        if i != j and energy(i, j) < -0.5:
            hbset.add((i, j))

def hb(i, j):
    if i < 0 or j < 0 or i >= n or j >= n:
        return False
    return (i, j) in hbset

def contig(i, k):
    if i < 0 or i+k >= n:
        return False
    for t in range(i+1, i+k+1):
        if not cont[t]:
            return False
    return True

helix = {}
for nt, code in ((4,'H'), (3,'G'), (5,'I')):
    marks = [False]*n
    for i in range(1, n):
        if contig(i-1, nt+1) and hb(i-1, i-1+nt) and hb(i, i+nt):
            for t in range(i, i+nt):
                marks[t] = True
    helix[code] = marks

bridges = []
for i in range(1, n-1):
    for j in range(i+3, n-1):
        if not (cont[i] and cont[i+1] and cont[j] and cont[j+1]):
            continue
        anti = (hb(i,j) and hb(j,i)) or (hb(i-1,j+1) and hb(j-1,i+1))
        par = (hb(i-1,j) and hb(j,i+1)) or (hb(j-1,i) and hb(i,j+1))
        if anti:
            bridges.append((i,j,'a'))
        elif par:
            bridges.append((i,j,'p'))

bset = set(bridges)
Em = [False]*n; Bm = [False]*n
for (i,j,t) in bridges:
    if t == 'p':
        lad = ((i+1,j+1,t) in bset) or ((i-1,j-1,t) in bset)
    else:
        lad = ((i+1,j-1,t) in bset) or ((i-1,j+1,t) in bset)
    if lad:
        Em[i] = True; Em[j] = True
    else:
        Bm[i] = True; Bm[j] = True

Tm = [False]*n
for nt in (3,4,5):
    for i in range(n):
        if contig(i, nt) and hb(i, i+nt):
            for t in range(i+1, i+nt):
                Tm[t] = True

Sm = [False]*n
for i in range(2, n-2):
    if not contig(i-2, 4):
        continue
    a = res[i-2]['atoms']['CA']; b = res[i]['atoms']['CA']; c = res[i+2]['atoms']['CA']
    v1 = (b[0]-a[0], b[1]-a[1], b[2]-a[2]); v2 = (c[0]-b[0], c[1]-b[1], c[2]-b[2])
    dot = sum(v1[k]*v2[k] for k in range(3))
    L1 = math.sqrt(sum(x*x for x in v1)); L2 = math.sqrt(sum(x*x for x in v2))
    ang = math.degrees(math.acos(max(-1.0, min(1.0, dot/(L1*L2)))))
    if ang > 70.0:
        Sm[i] = True

ss = []
for i in range(n):
    if helix['H'][i]: ss.append('H')
    elif Bm[i]: ss.append('B')
    elif Em[i]: ss.append('E')
    elif helix['G'][i]: ss.append('G')
    elif helix['I'][i]: ss.append('I')
    elif Tm[i]: ss.append('T')
    elif Sm[i]: ss.append('S')
    else: ss.append('-')

names = {'H':'H  alpha-helix', 'B':'B  isolated beta-bridge', 'E':'E  extended strand (beta-sheet)', 'G':'G  3-10 helix', 'I':'I  pi-helix', 'T':'T  hydrogen-bonded turn', 'S':'S  bend', '-':'-  coil / other'}

print('File: ' + path)
print('Residues with complete backbone (N,CA,C,O): ' + str(n))
print('Chains: ' + ','.join(sorted(set(r['chain'] for r in res))))
print('Backbone H-bonds found (Kabsch-Sander E < -0.5 kcal/mol): ' + str(len(hbset)))
print('')
print('=== SECONDARY STRUCTURE COMPOSITION ===')
for code in ('H','B','E','G','I','T','S','-'):
    c = ss.count(code)
    print('%-34s %4d residues  %6.2f %%' % (names[code], c, 100.0*c/n))
print('')
print('Summary: helix (H+G+I) = %d (%.2f%%), beta (E+B) = %d (%.2f%%), turn/bend (T+S) = %d (%.2f%%), coil = %d (%.2f%%)' % (
    ss.count('H')+ss.count('G')+ss.count('I'), 100.0*(ss.count('H')+ss.count('G')+ss.count('I'))/n,
    ss.count('E')+ss.count('B'), 100.0*(ss.count('E')+ss.count('B'))/n,
    ss.count('T')+ss.count('S'), 100.0*(ss.count('T')+ss.count('S'))/n,
    ss.count('-'), 100.0*ss.count('-')/n))
print('')
print('=== PER-RESIDUE STRING (residue 1 -> ' + str(n) + ') ===')
for s in range(0, n, 60):
    print('%4s  %s' % (res[s]['resseq'], ''.join(ss[s:s+60])))
print('')
print('=== SEGMENTS ===')
i = 0
while i < n:
    j = i
    while j+1 < n and ss[j+1] == ss[i] and res[j+1]['chain'] == res[i]['chain']:
        j += 1
    if ss[i] != '-':
        print('%s  chain %s  %s%s - %s%s  (%d res)' % (ss[i], res[i]['chain'], res[i]['resname'], res[i]['resseq'], res[j]['resname'], res[j]['resseq'], j-i+1))
    i = j+1
print('')
print('=== PDB-DEPOSITED HELIX / SHEET RECORDS (for cross-check) ===')
for l in helix_recs + sheet_recs:
    print(l)
if not (helix_recs or sheet_recs):
    print('(none present in file)')
PYEOF
